 readonly ExpandedWorkshop garage;readonly List<Texture2D> textures=new List<Texture2D>();readonly List<Material> previewMaterials=new List<Material>();
 readonly Color ink=new Color(.045f,.07f,.10f),panel=new Color(.075f,.11f,.15f),muted=new Color(.65f,.72f,.77f),accent=new Color(.22f,.87f,.76f),amber=new Color(1,.72f,.35f);
 GUIStyle card,selectedCard,button,primary,disabled,field;bool styles,clearFocus;Vector2 scroll,detailScroll;public string Search="";string category="All";public bool Typing{get;private set;}
 GameObject previewRoot;Camera previewCamera;RenderTexture preview;float angle=28,lastRender=-1;
