 public ExpandedWorkshopView(ExpandedWorkshop source){garage=source;}
 GUIStyle Surface(Color color){int size=24;var texture=new Texture2D(size,size,TextureFormat.RGBA32,false){name="Garage UI rounded surface"};for(int y=0;y<size;y++)for(int x=0;x<size;x++){float qx=Mathf.Abs(x-11.5f)-5.5f,qy=Mathf.Abs(y-11.5f)-5.5f;float distance=new Vector2(Mathf.Max(qx,0),Mathf.Max(qy,0)).magnitude+Mathf.Min(Mathf.Max(qx,qy),0)-6;texture.SetPixel(x,y,new Color(color.r,color.g,color.b,color.a*Mathf.Clamp01(.5f-distance)));}texture.Apply();textures.Add(texture);return new GUIStyle{normal={background=texture},border=new RectOffset(8,8,8,8)};}
 void EnsureStyles(){if(styles)return;styles=true;card=Surface(panel);card.hover.background=Surface(new Color(.10f,.16f,.20f)).normal.background;card.active.background=card.hover.background;selectedCard=Surface(new Color(.10f,.24f,.25f));selectedCard.hover.background=selectedCard.normal.background;button=Surface(new Color(.12f,.18f,.23f));button.hover.background=Surface(new Color(.18f,.28f,.33f)).normal.background;button.active.background=selectedCard.normal.background;button.normal.textColor=Color.white;button.hover.textColor=Color.white;button.active.textColor=Color.white;button.fontSize=17;button.fontStyle=FontStyle.Bold;button.alignment=TextAnchor.MiddleCenter;primary=new GUIStyle(button);primary.normal.background=Surface(accent).normal.background;primary.normal.textColor=ink;primary.hover.background=Surface(new Color(.37f,.96f,.84f)).normal.background;primary.hover.textColor=ink;disabled=new GUIStyle(button);disabled.normal.textColor=muted;field=new GUIStyle(GUI.skin.textField){fontSize=17,padding=new RectOffset(14,12,10,8)};field.normal.background=button.normal.background;field.focused.background=selectedCard.normal.background;field.normal.textColor=Color.white;field.focused.textColor=Color.white;}
 GUIStyle Text(int size,Color color,bool bold=false,bool wrap=false,TextAnchor align=TextAnchor.UpperLeft){var s=new GUIStyle(GUI.skin.label){fontSize=Mathf.Max(size,15),fontStyle=bold?FontStyle.Bold:FontStyle.Normal,wordWrap=wrap,alignment=align,padding=new RectOffset(0,0,0,0)};s.normal.textColor=color;return s;}
 void Label(Rect r,string value,int size=17,Color? color=null,bool bold=false,bool wrap=false){GUI.Label(r,value,Text(size,color??Color.white,bold,wrap));}
 void Fill(Rect r,Color color){var old=GUI.color;GUI.color=color;GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=old;}

 public void Open(){ClearFilter();CreatePreview();}
 public void ClearFilter(){Search="";category="All";scroll=Vector2.zero;clearFocus=true;}
 public void EndSearch(){clearFocus=true;Typing=false;}
 public List<WorkshopOffer> Visible()=>garage.Catalog.offers.Where(o=>(category=="All"||o.category==category)&&(o.name+" "+o.description).IndexOf(Search,StringComparison.OrdinalIgnoreCase)>=0).ToList();
 public void Advance(int direction){var list=Visible();if(list.Count==0)return;int i=list.FindIndex(o=>o.id==garage.SelectedId);garage.SelectedId=list[(i+direction+list.Count)%list.Count].id;detailScroll=Vector2.zero;}
 string Money(int n)=>n.ToString("N0",System.Globalization.CultureInfo.InvariantCulture)+" cr";
 public void Close(){Typing=false;if(previewCamera!=null)previewCamera.targetTexture=null;if(previewRoot!=null)UnityEngine.Object.Destroy(previewRoot);if(preview!=null){preview.Release();UnityEngine.Object.Destroy(preview);}foreach(var m in previewMaterials)UnityEngine.Object.Destroy(m);previewMaterials.Clear();previewRoot=null;previewCamera=null;preview=null;}
 void CreatePreview(){Close();if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)return;previewRoot=new GameObject("Garage render preview | visual only");previewRoot.transform.position=new Vector3(0,-1000,0);var source=garage.Car.transform;
  foreach(var filter in source.GetComponentsInChildren<MeshFilter>()){var renderer=filter.GetComponent<MeshRenderer>();if(renderer==null||!renderer.enabled||!renderer.gameObject.activeInHierarchy)continue;var g=new GameObject(filter.name);g.layer=31;g.transform.SetParent(previewRoot.transform,false);g.transform.localPosition=source.InverseTransformPoint(filter.transform.position);g.transform.localRotation=Quaternion.Inverse(source.rotation)*filter.transform.rotation;g.transform.localScale=filter.transform.lossyScale;g.AddComponent<MeshFilter>().sharedMesh=filter.sharedMesh;var copy=g.AddComponent<MeshRenderer>();var mats=new Material[renderer.sharedMaterials.Length];for(int i=0;i<mats.Length;i++){mats[i]=new Material(renderer.sharedMaterials[i]);if(mats[i].HasProperty("_Glossiness"))mats[i].SetFloat("_Glossiness",.3f);previewMaterials.Add(mats[i]);}copy.sharedMaterials=mats;}
  var cameraObject=new GameObject("Garage preview camera");cameraObject.transform.SetParent(previewRoot.transform,false);previewCamera=cameraObject.AddComponent<Camera>();previewCamera.cullingMask=1<<31;previewCamera.clearFlags=CameraClearFlags.SolidColor;previewCamera.backgroundColor=ink;previewCamera.fieldOfView=34;previewCamera.nearClipPlane=.1f;previewCamera.farClipPlane=30;previewCamera.enabled=false;preview=new RenderTexture(640,400,16){name="Garage car render"};preview.Create();previewCamera.targetTexture=preview;angle=28;lastRender=-1;
 }
 void RenderPreview(){if(previewCamera==null)return;if(Event.current.type!=EventType.Repaint||Time.unscaledTime-lastRender<.04f)return;lastRender=Time.unscaledTime;var root=previewRoot.transform.position;previewCamera.transform.position=root+Quaternion.Euler(0,angle,0)*new Vector3(0,1.8f,6.2f);previewCamera.transform.LookAt(root+Vector3.up*.72f);previewCamera.Render();}

