  Label(new Rect(24,25,1050,43),"HARBOR VALE / WORKSHOP",32,Color.white,true);Label(new Rect(24,78,1000,27),garage.IsTest?"APEX LAB / Free test parts reset each visit. Career money stays separate.":"One parts counter / Paid stages, matched hardware and saved builds.",17,muted);Label(new Rect(1120,30,285,28),garage.IsTest?"FREE APEX TEST":Money(garage.Credits),23,accent,true);
