  Label(new Rect(42,466,245,32),current.PeakKw().ToString("F1")+" kW / "+current.torque.Max().ToString("F0")+" Nm",21,Color.white,true);Label(new Rect(42,516,245,44),"Shift "+current.shiftSeconds.ToString("F3")+" s\nBrake target "+current.brakeDeceleration.ToString("F1")+" m/s²",17,muted,false,true);Label(new Rect(42,581,245,140),"Gearbox S"+b.gearboxStage+" / Cooling S"+b.coolingStage+"\nBrakes S"+b.brakeStage+" / Tires S"+b.tireStage+"\nIntake S"+b.intakeStage+" / Exhaust S"+b.exhaustStage+"\n"+b.sound+" calibration S"+b.soundStage,17,muted,false,true);Label(new Rect(42,742,245,40),garage.IsTest?"Temporary changes only":"Payments and build saved together",15,muted,false,true);
  for(int i=0;i<categories.Length;i++){var r=new Rect(328+(i%5)*130,124+(i/5)*44,122,36);if(GUI.Button(r,categories[i],category==categories[i]?primary:button)){category=categories[i];scroll=Vector2.zero;}}
  GUI.SetNextControlName("workshopSearch");Search=GUI.TextField(new Rect(328,218,610,40),Search,60,field);if(GUI.Button(new Rect(944,218,34,40),"×",button))ClearFilter();Typing=GUI.GetNameOfFocusedControl()=="workshopSearch";if(Search.Length==0&&!Typing)Label(new Rect(341,230,575,24),"Search parts by name or purpose…",16,muted);var list=Visible();if(list.Count>0&&!list.Any(o=>o.id==garage.SelectedId))garage.SelectedId=list[0].id;Label(new Rect(328,270,640,23),list.Count+" PARTS / Select a stage to compare",15,muted);
  scroll=GUI.BeginScrollView(new Rect(328,304,650,310),scroll,new Rect(0,0,625,Mathf.Max(310,Mathf.Ceil(list.Count/2f)*136)));for(int i=0;i<list.Count;i++){var o=list[i];var r=new Rect((i%2)*315,(i/2)*136,305,124);if(GUI.Button(r,"",o.id==garage.SelectedId?selectedCard:card)){garage.SelectedId=o.id;detailScroll=Vector2.zero;}Label(new Rect(r.x+14,r.y+10,276,43),o.name,18,Color.white,true,true);Label(new Rect(r.x+14,r.y+57,276,24),garage.IsTest?"FREE TEST PART":Money(o.price),18,accent,true);string status=o.apexOnly&&!garage.IsTest?"Apex test only":garage.Catalog.Installed(b,o)?"✓ Installed":garage.Catalog.Requirement(b,o)??"Ready to install";Label(new Rect(r.x+14,r.y+89,276,29),status,14,status=="Ready to install"?accent:muted,false,true);}GUI.EndScrollView();
  if(list.Count==0){Label(new Rect(350,360,550,80),"No matching parts. Clear search or choose another category.",22,muted,false,true);if(GUI.Button(new Rect(1020,250,370,52),"Clear search",primary))ClearFilter();Footer();GUI.matrix=old;return;}
  var selected=garage.Catalog.Find(garage.SelectedId);bool installed=garage.Catalog.Installed(b,selected);FinchDefinition after=current;try{after=garage.Catalog.Preview(b,selected);}catch{}GUI.Box(new Rect(328,636,650,153),"",card);Label(new Rect(344,646,610,24),"TORQUE / Gray current · Teal complete required setup",14,muted);Plot(new Rect(350,685,600,70),current,after);
  GUI.Box(new Rect(1000,124,416,665),"",card);Label(new Rect(1020,145,370,60),selected.name,27,Color.white,true,true);Label(new Rect(1020,217,370,32),garage.IsTest?"FREE TEST PART":Money(selected.price),25,accent,true);
  detailScroll=GUI.BeginScrollView(new Rect(1020,266,376,340),detailScroll,new Rect(0,0,354,Mathf.Max(340,Text(16,muted,false,true).CalcHeight(new GUIContent(selected.description),350)+170+garage.Catalog.MissingPath(b,selected).Count*28)));
  float descH=Mathf.Max(100,Text(16,muted,false,true).CalcHeight(new GUIContent(selected.description),350));Label(new Rect(0,0,350,descH),selected.description,16,muted,false,true);Label(new Rect(0,descH+10,350,26),current.PeakKw().ToString("F1")+" → "+after.PeakKw().ToString("F1")+" kW",20,accent,true);Label(new Rect(0,descH+41,350,25),current.torque.Max().ToString("F0")+" → "+after.torque.Max().ToString("F0")+" Nm",17,muted);Label(new Rect(0,descH+70,350,25),"Shift "+current.shiftSeconds.ToString("F3")+" → "+after.shiftSeconds.ToString("F3")+" s",16,muted);Label(new Rect(0,descH+99,350,25),"Brakes "+current.brakeDeceleration.ToString("F1")+" → "+after.brakeDeceleration.ToString("F1")+" m/s²",16,muted);int row=0;foreach(var item in garage.Catalog.MissingPath(b,selected))Label(new Rect(0,descH+135+row++*28,350,28),"○ "+item.name+(garage.IsTest?"":" · "+Money(item.price)),14,muted);GUI.EndScrollView();
  string reason=garage.Requirement(selected);if(reason!=null&&!installed&&GUI.Button(new Rect(1020,614,370,34),"View next required part →",button))garage.GuideToRequirement();Label(new Rect(1020,656,370,63),garage.Message??(installed?"Installed on this build.":garage.IsTest?(reason??"Ready to test. No credits spent."):"Full path: "+Money(garage.TotalPathCost(selected))+"\n"+(reason??("Balance after install: "+Money(garage.Credits-selected.price)))),16,muted,false,true);
  var action=new Rect(1020,731,370,44);if(reason==null){if(GUI.Button(action,garage.IsTest?"Install test part":"Install · "+Money(selected.price),primary))garage.Install(selected.id);}else GUI.Box(action,installed?"INSTALLED":"LOCKED / See requirements",disabled);Footer();GUI.matrix=old;
 }
 void Footer(){GUI.Box(new Rect(24,812,1392,64),"",card);Label(new Rect(42,835,950,26),Typing?"Esc leaves search":"↑ / ↓ Browse · Enter Install · Esc / G Return to driving",16,muted);if(GUI.Button(new Rect(1100,825,296,40),"Return to driving",primary))garage.Close();}
 void Plot(Rect r,FinchDefinition a,FinchDefinition b){float max=Mathf.Ceil(Mathf.Max(a.torque.Max(),b.torque.Max())/20)*20;Label(new Rect(r.xMax-100,r.y-13,100,20),max.ToString("F0")+" Nm",13,muted);foreach(var item in new[]{a,b}){var matrix=GUI.matrix;var old=GUI.color;GUI.color=item==a?muted:accent;for(int i=1;i<item.rpm.Length;i++){var x=new Vector2(r.x+(item.rpm[i-1]-900)/5600*r.width,r.yMax-item.torque[i-1]/max*r.height);var y=new Vector2(r.x+(item.rpm[i]-900)/5600*r.width,r.yMax-item.torque[i]/max*r.height);GUI.matrix=matrix*Matrix4x4.TRS(new Vector3(x.x,x.y),Quaternion.Euler(0,0,Mathf.Atan2(y.y-x.y,y.x-x.x)*Mathf.Rad2Deg),Vector3.one);GUI.DrawTexture(new Rect(0,0,Vector2.Distance(x,y),2),Texture2D.whiteTexture);GUI.matrix=matrix;}GUI.color=old;}Label(new Rect(r.x,r.yMax+2,580,20),"900 RPM                                                      6500 RPM",13,muted);}
